INSERT INTO `item_unique` (`key`, `name`, `base_entry`, `item_level`, `required_level`, `description`, `creature_entry`, `chance`) VALUES
('hogger', 'Hogger''s Gnawbone', 1009, 14, 9, 'Still warm. Hogger was not done with it.', 448, 0.5),
('vancleef', 'VanCleef''s Ledger-Blade', 5540, 23, 18, 'Every debt Stormwind owes is carved into the blade.', 639, 1),
('mutanus', 'Mantle of the Waking Dream', 4314, 23, 18, 'Naralex dreams on; the mantle remembers what woke.', 3654, 1),
('arugal', 'Arugal''s Worgen-Bound Cloak', 2316, 24, 19, 'Stitched from the first pelt of the Moonrage.', 4275, 1),
('charlga', 'Thornweave Leggings of Charlga', 4830, 30, 25, 'Woven from the thorns that grew from her blood.', 4421, 1),
('morladim', 'Mor''Ladim''s Grave-Ring', 1116, 33, 28, 'He swore to return for her. The ring kept the promise.', 522, 0.5),
('thalnos', 'Thalnos''s Bloodstained Vestments', 1997, 36, 31, 'The stains are older than the Crusade.', 4543, 1),
('herod', 'Herod''s Crusading Pauldrons', 3765, 42, 37, 'Blades of the Scarlet champion, worn to the bone.', 3975, 1),
('theradras', 'Girdle of the Earthmother''s Grief', 8129, 51, 46, 'Theradras mourns, and the earth answers.', 12201, 1),
('eranikus', 'Nightmare-Touched Grips', 8260, 53, 48, 'The Emerald Dream is not what it was.', 5709, 1),
('rivendare', 'The Baron''s Deathcharger Blade', 15256, 62, 58, 'Rivendare''s last order: ride.', 10440, 1);
